  "prediction_basis_card_ids": ["C01", "C02", "C04", "C05", "C12", "C14", "C19", "C20", "C24", "C28"],
  "claims": [
    {
      "claim": "Vinorelbine, a large lipophilic alkaloid, has measured absolute oral bioavailability of 43 ± 14% for the soft-gel capsule in fasted patients and 36–43% with food; a liquid-filled capsule gave 27 ± 14% and 25 ± 11%, all mean values above the 20% threshold.",
      "card_ids": ["C02", "C04", "C05", "C12", "C14", "C24"]
    },
    {
      "claim": "LCS1269, which shares the indolocarbazole-lactam core with the query, is predicted to have human bioavailability greater than 30% based on intestinal absorption.",
      "card_ids": ["C19"]
    },
    {
      "claim": "Ondansetron, a carbazole-containing drug, has absolute oral bioavailability of 50–65% in fasted volunteers and 40% after rifampin pretreatment, supporting that this scaffold can achieve F ≥ 20%.",
      "card_ids": ["C01", "C03", "C20", "C28"]
    },
    {
      "claim": "The low absolute bioavailability of penicillin V in fasted pigs (18.9 ± 4.8%) is not transferable to the query because the query is not a beta-lactam and the record is species- and molecule-specific.",
      "card_ids": ["C22", "C25"]
    },
    {
      "claim": "The L3 oral AUC/Cmax records concern cebranopadol, ramosetron, and rifampin, not the query or close structural analogs, and provide no threshold-relevant oral bioavailability evidence for the query.",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability or oral AUC/Cmax data are available for the query molecule itself.",
    "The LCS1269 record is a predicted HIA-based value rather than a measured absolute bioavailability.",
    "Vinorelbine and ondansetron are structural analogs with different scaffolds/substituents; transfer is indirect.",
    "Vinorelbine bioavailability is formulation-dependent, and the query formulation is unspecified.",
    "No query-specific solubility, permeability, or first-pass clearance data are available.",
    "L3 exposure records are for unrelated molecules and do not inform the query."
  ],
  "decision_summary": "L3 adds only oral Cmax/AUC records for cebranopadol, ramosetron, and rifampin; none are structurally or mechanistically applicable to the query, so the prior high prediction is unchanged. The transferable analog evidence — vinorelbine (~40%), LCS1269 (predicted >30%), and ondansetron (50–65%) — continues to support F ≥ 20%, and no affirmative threshold-relevant low-F evidence applies to the query."
}

